"""Fresh evaluation panel for GRAPH6_CONFIRMATION_001 (owner-directed).

Builds a PRE-REGISTERED panel of NEW whole-part cases inside the SAME supported
difficulty and vocabulary as the teaching records:

* 30 graph families, one question per operation => 90 scored cases;
* every case is generated by the frozen lesson generator
  (``lessons._whole_part_exercises``) — no new template, no new vocabulary;
* the training/practice records and the whole previously examined dataset
  (seed 20260909, all splits, which contains the examined attempt-010 panel)
  are excluded — by exact record id AND by a label-invariant structural
  signature, so a TRIVIALLY RENAMED DUPLICATE of a used case is excluded too;
* cases from one family are kept together and reported as one family.

Boundary: this module only CONSTRUCTS and AUDITS the panel. It never trains,
never selects a checkpoint, never fits the tokenizer (the tokenizer is fitted on
training records only), and never exposes an answer to a learner: the answers
travel in the panel record and are compared only after the predictions are
recorded (see ``confirmation.py``).
"""
from __future__ import annotations

from functools import lru_cache

from . import lessons
from .graph import canonical, digest, require

PANEL_SCHEMA = "cas-graph-training-fresh-panel/1"
PANEL_SEED = 20260920
PANEL_SEED_002 = 20260930
PANEL_FAMILY_COUNT = 30
PANEL_FAMILY_BASE = 41000
PANEL_FAMILY_BASE_002 = 51000      # a disjoint family-seed region for panel 002
PANEL_SPLIT = "fresh"
PANEL_OPS = tuple(lessons.WHOLE_PART_OPS)          # LIST_PARTS, FIND_SHARED_PART, REACHED_VIA
EXCLUDED_DATASET_SEEDS = (20260909,)               # includes the examined attempt-010 panel
# Panels already EXAMINED during development: their cases are excluded from any
# new panel, so a later improvement claim is measured on untouched material.
EXAMINED_PANEL_SEEDS = (PANEL_SEED,)
MAX_FAMILY_PROBES = 3000


def _node_roles(record):
    nodes = {item["identifier"]: item for item in record["nodes"]}
    outgoing = {identifier: [] for identifier in nodes}
    incoming = {identifier: [] for identifier in nodes}
    for relation in record["relations"]:
        outgoing[relation["source"]].append((relation["kind"], relation["target"]))
        incoming[relation["target"]].append((relation["kind"], relation["source"]))
    return nodes, outgoing, incoming


def _structural_ids(record, rounds=4):
    """Label-invariant node types: refinement over kind + relation neighbourhood.

    Labels never enter, so two cases that differ only by renaming produce the
    same types. Nodes that remain indistinguishable after the refinement share
    a type id, which is exactly the right notion for "same case up to renaming".
    """
    nodes, outgoing, incoming = _node_roles(record["graph"])
    types = {identifier: (node["kind"], tuple(sorted(name for name, _ in node["fields"])))
             for identifier, node in nodes.items()}
    for _ in range(rounds):
        types = {
            identifier: (types[identifier],
                         tuple(sorted((kind, types[target]) for kind, target in outgoing[identifier])),
                         tuple(sorted((kind, types[source]) for kind, source in incoming[identifier])))
            for identifier in nodes}
    order = sorted(set(types.values()))
    ids = {value: index for index, value in enumerate(order)}
    return {identifier: ids[types[identifier]] for identifier in nodes}


def _role(value, node_ids):
    """Map a label-bearing answer/question value to its label-invariant role."""
    if isinstance(value, list):
        return ["list"] + sorted(_role(item, node_ids) for item in value)
    if isinstance(value, str) and value.startswith("via:"):
        return ["via", node_ids.get(value[4:], value[4:])]
    if value in node_ids:
        return ["node", node_ids[value]]
    return ["literal", value]


def structural_signature(record):
    """Label-invariant signature of one case: structure + question + answer +
    option multiset. Two cases with the same signature are the same case up to
    renaming."""
    node_ids = _structural_ids(record)
    edges = sorted((relation["kind"], node_ids[relation["source"]],
                    node_ids[relation["target"]]) for relation in record["graph"]["relations"])
    question = sorted((key, _role(value, node_ids))
                      for key, value in record["question"].items())
    return {"schema": "cas-graph-training-fresh-case-signature/1",
            "op": record["op"],
            "node_types": sorted(node_ids.values()),
            "edges": edges,
            "question": question,
            "answer": _role(record["correct"], node_ids),
            "options": sorted((_role(option, node_ids) for option in record["options"]),
                              key=canonical)}


def signature_key(record):
    return digest(canonical(structural_signature(record)))


def _reach_label(correct):
    if correct == "direct" or correct == "absent":
        return correct
    if isinstance(correct, str) and correct.startswith("via:"):
        return "via"
    return "other"


def _select_case(op, records, family_seed, preferred_reach=None):
    """One record per operation, deterministically chosen.

    LIST_PARTS / FIND_SHARED_PART: the generator's first record (same form as
    the teaching records). REACHED_VIA: the panel builder states which reach
    label it still needs (direct / via / absent); the family's own generator
    order supplies the rest, rotated by the family seed. The choice depends only
    on the family seed and the declared quota — never on any answer or on any
    model output.
    """
    if op != "REACHED_VIA":
        return records[0]
    order = []
    if preferred_reach is not None:
        order.append(preferred_reach)
    preference = ("direct", "via", "absent")
    offset = family_seed % len(preference)
    order.extend(label for label in preference[offset:] + preference[:offset]
                 if label not in order)
    for label in order:
        for record in records:
            if _reach_label(record["correct"]) == label:
                return record
    return records[0]


def _family_records(family_seed, split=PANEL_SPLIT):
    """All whole-part records of one family, grouped by operation."""
    by_op = {}
    for record in lessons._whole_part_exercises(family_seed, split):
        by_op.setdefault(record["op"], []).append(record)
    return by_op


def examined_panel_index(panel_seeds=EXAMINED_PANEL_SEEDS):
    """Ids and signatures of panels that have already been examined during
    development. They are excluded from any new panel."""
    ids, signatures = set(), set()
    for seed in panel_seeds:
        panel = build_panel(panel_seed=seed)
        for case in panel["cases"]:
            ids.add(case["record_id"])
            signatures.add(case["signature"])
    return ids, signatures


def used_index(excluded_seeds=EXCLUDED_DATASET_SEEDS, excluded_panels=(),
               excluded_curricula=()):
    """Ids and signatures of every case the learner has already seen: the
    training/practice records, the whole previously examined dataset, any panel
    development has already examined, and any curriculum built for a candidate."""
    return _used_index(tuple(excluded_seeds), tuple(excluded_panels),
                       tuple(excluded_curricula))


@lru_cache(maxsize=8)
def _used_index(excluded_seeds, excluded_panels, excluded_curricula):
    ids, signatures = set(), set()
    for seed in excluded_seeds:
        for records in lessons.build_dataset(seed=seed).values():
            for record in records:
                if record["family"] != "whole_part" or record["op"] not in PANEL_OPS:
                    continue
                ids.add(record["record_id"])
                signatures.add(signature_key(record))
    if excluded_panels:
        panel_ids, panel_signatures = examined_panel_index(excluded_panels)
        ids |= panel_ids
        signatures |= panel_signatures
    if excluded_curricula:
        from . import curriculum
        for seed in excluded_curricula:
            for record in curriculum.varied_records(seed=seed):
                ids.add(record["record_id"])
                signatures.add(signature_key(record))
    return ids, signatures


def candidate_families(*, panel_seed=PANEL_SEED, family_base=PANEL_FAMILY_BASE,
                       max_probes=MAX_FAMILY_PROBES,
                       excluded_seeds=EXCLUDED_DATASET_SEEDS, excluded_panels=()):
    """Every fresh family that passes the exclusion, in deterministic order.

    A family passes only if EVERY whole-part record it generates is new: no
    exact record id from the used set and no label-invariant signature from the
    used set (so a renamed duplicate of a used case is rejected too). Checking
    the whole family, not just the selected cases, keeps the rejection
    independent of which cases the panel ends up choosing.

    This family-level rule is what produced the examined 90-case panel
    (digest ``d1076de3…``); it is kept exactly so that panel stays
    reproducible. A panel built from a NEW shape bank, where the frozen
    generator's pattern space is already exhausted, is ``final_panel.py``.
    """
    used_ids, used_signatures = used_index(excluded_seeds, excluded_panels)
    accepted = []
    rejected = {"missing_op": 0, "used_case": 0}
    for probe in range(1, max_probes + 1):
        family_seed = family_base + panel_seed % 1000 + probe
        by_op = _family_records(family_seed)
        if set(by_op) != set(PANEL_OPS):
            rejected["missing_op"] += 1
            continue
        flat = [record for records in by_op.values() for record in records]
        if any(signature_key(record) in used_signatures for record in flat) or \
                any(record["record_id"] in used_ids for record in flat):
            rejected["used_case"] += 1
            continue
        accepted.append({"family_seed": family_seed, "by_op": by_op})
    return accepted, rejected


def _case_item(family_id, family_seed, op, record):
    return {"family_id": family_id, "op": op, "record_id": record["record_id"],
            "signature": signature_key(record), "record": record}


def build_panel(*, panel_seed=PANEL_SEED, family_count=PANEL_FAMILY_COUNT,
                family_base=PANEL_FAMILY_BASE, max_probes=MAX_FAMILY_PROBES,
                excluded_seeds=EXCLUDED_DATASET_SEEDS, excluded_panels=(),
                reach_quota=None):
    """Deterministic panel construction with declared quotas and diversification.

    Every accepted family is new (exclusion above). REACHED_VIA is spread over
    the three reach labels by a declared quota (default an even split), because
    the generator's first REACHED_VIA record is always the 'direct' case and a
    panel made only of 'direct' questions would not test the operation's range.
    Among the candidates that can still fill the open quota, the builder prefers
    the family that adds the most case patterns not yet in the panel; ties break
    on the lower family seed, so the panel is reproducible.
    """
    quota = dict(reach_quota or {"direct": family_count // 3,
                                 "via": family_count // 3,
                                 "absent": family_count // 3})
    candidates, rejected = candidate_families(
        panel_seed=panel_seed, family_base=family_base, max_probes=max_probes,
        excluded_seeds=excluded_seeds, excluded_panels=excluded_panels)
    require(len(candidates) >= family_count, "FRESH_PANEL_POOL_EXHAUSTED")
    chosen, chosen_signatures, chosen_triples = [], set(), set()
    remaining = dict(quota)
    pool = list(candidates)
    while len(chosen) < family_count:
        open_labels = [label for label, count in remaining.items() if count > 0]
        preferred = max(open_labels, key=lambda label: (remaining[label], label)) \
            if open_labels else None

        def reach_label_of(candidate, label):
            return _reach_label(_select_case(
                "REACHED_VIA", candidate["by_op"]["REACHED_VIA"],
                candidate["family_seed"], label)["correct"]) == label

        def prepare(candidate, wanted):
            target = wanted if (wanted is not None and reach_label_of(candidate, wanted)) \
                else _reach_label(_select_case(
                    "REACHED_VIA", candidate["by_op"]["REACHED_VIA"],
                    candidate["family_seed"])["correct"])
            cases = [_case_item("pending", candidate["family_seed"], op,
                                _select_case(op, candidate["by_op"][op],
                                             candidate["family_seed"],
                                             target if op == "REACHED_VIA" else None))
                     for op in PANEL_OPS]
            triple = digest(canonical(sorted(case["signature"] for case in cases)))
            return target, cases, triple

        best, best_key = None, None
        for candidate in pool:
            target, cases, triple = prepare(candidate, preferred)
            if triple in chosen_triples:
                continue
            if preferred is not None and target != preferred:
                continue
            novelty = sum(1 for case in cases if case["signature"] not in chosen_signatures)
            key = (-novelty, candidate["family_seed"])
            if best_key is None or key < best_key:
                best, best_key = candidate, key
        if best is None and preferred is not None:      # quota unfillable: relax
            remaining[preferred] = 0
            continue
        require(best is not None, "FRESH_PANEL_POOL_EXHAUSTED")
        pool.remove(best)
        target, cases, triple = prepare(best, preferred)
        family_id = "family_%02d" % (len(chosen) + 1)
        for case in cases:
            case["family_id"] = family_id
        chosen.append({"family_id": family_id, "family_seed": best["family_seed"],
                       "family_signature": triple, "cases": cases})
        chosen_signatures.update(case["signature"] for case in cases)
        chosen_triples.add(chosen[-1]["family_signature"])
        if target in remaining and remaining[target] > 0:
            remaining[target] -= 1
    cases = [case for family in chosen for case in family["cases"]]
    panel = {
        "schema": PANEL_SCHEMA,
        "panel_seed": panel_seed,
        "family_count": len(chosen),
        "case_count": len(cases),
        "ops": list(PANEL_OPS),
        "cases_per_op": {op: sum(1 for case in cases if case["op"] == op)
                         for op in PANEL_OPS},
        "excluded_dataset_seeds": list(excluded_seeds),
        "excluded_panels": list(excluded_panels),
        "excluded_case_ids": len(used_index(excluded_seeds, excluded_panels)[0]),
        "excluded_signatures": len(used_index(excluded_seeds, excluded_panels)[1]),
        "candidate_families": len(candidates),
        "rejected": rejected,
        "reach_quota": quota,
        "distinct_family_patterns": len({family["family_signature"] for family in chosen}),
        "distinct_case_patterns": len({case["signature"] for case in cases}),
        "reach_label_counts": {label: sum(1 for case in cases
                                          if case["op"] == "REACHED_VIA"
                                          and _reach_label(case["record"]["correct"]) == label)
                               for label in ("direct", "via", "absent")},
        "families": chosen,
        "cases": cases,
        "boundary": ("fresh panel only: no training, no checkpoint selection, "
                     "no tokenizer fitting, no answer exposure before the "
                     "registered predictions are sealed"),
    }
    validate_panel(panel)
    return panel


def validate_panel(panel):
    require(panel["schema"] == PANEL_SCHEMA, "FRESH_PANEL_SCHEMA")
    require(panel["family_count"] == len(panel["families"]) == PANEL_FAMILY_COUNT,
            "FRESH_PANEL_FAMILY_COUNT")
    cases = panel["cases"]
    require(len(cases) == panel["case_count"] == PANEL_FAMILY_COUNT * len(PANEL_OPS),
            "FRESH_PANEL_CASE_COUNT")
    for op in PANEL_OPS:
        require(panel["cases_per_op"][op] == PANEL_FAMILY_COUNT,
                "FRESH_PANEL_CASES_PER_OP:" + op)
    ids = [case["record_id"] for case in cases]
    require(len(ids) == len(set(ids)), "FRESH_PANEL_DUPLICATE_CASE_ID")
    triples = [family["family_signature"] for family in panel["families"]]
    require(len(triples) == len(set(triples)), "FRESH_PANEL_DUPLICATE_FAMILY_PATTERN")
    used_ids, used_signatures = used_index(panel["excluded_dataset_seeds"],
                                          tuple(panel.get("excluded_panels", ())))
    require(not (set(ids) & used_ids), "FRESH_PANEL_REUSES_USED_CASE")
    require(not ({case["signature"] for case in cases} & used_signatures),
            "FRESH_PANEL_REUSES_RENAMED_USED_CASE")
    for label in ("direct", "via", "absent"):
        require(panel["reach_label_counts"][label] >= 5,
                "FRESH_PANEL_REACH_COVERAGE:" + label)
    for family in panel["families"]:
        require(len(family["cases"]) == len(PANEL_OPS),
                "FRESH_PANEL_FAMILY_INCOMPLETE")
        require({case["op"] for case in family["cases"]} == set(PANEL_OPS),
                "FRESH_PANEL_FAMILY_OPS")
        require(all(case["family_id"] == family["family_id"] for case in family["cases"]),
                "FRESH_PANEL_FAMILY_GROUPING")
    return panel


def panel_digest(panel):
    """Stable identity of the panel content (records only, no audit counters)."""
    return digest(canonical([{"family_id": family["family_id"],
                              "family_seed": family["family_seed"],
                              "cases": [{"op": case["op"],
                                         "record_id": case["record_id"]}
                                        for case in family["cases"]]}
                             for family in panel["families"]]))


def panel_cases(panel):
    """Flattened case list: (family_id, record)."""
    return [(case["family_id"], case["record"]) for case in panel["cases"]]
